const { existsSync } = await import('node:fs');
const imagePath = process.env.IMAGE_PATH;
if (!imagePath) { throw new Error('Missing IMAGE_PATH env var'); }
if (!existsSync(imagePath)) { throw new Error('Image file not found at ' + imagePath); }
globalThis.imagePath = imagePath;
globalThis.pdfPath = '/tmp/output.pdf';

const { PDFDocument } = await import('pdf-lib');
const { readFileSync, writeFileSync } = await import('node:fs');
const imgBytes = readFileSync(globalThis.imagePath);
const pdfDoc = await PDFDocument.create();
const pngImage = await pdfDoc.embedPng(imgBytes);
const pngDims = pngImage.scale(1);
const page = pdfDoc.addPage([pngDims.width, pngDims.height]);
page.drawImage(pngImage, { x: 0, y: 0, width: pngDims.width, height: pngDims.height });
const pdfBytes = await pdfDoc.save();
writeFileSync(globalThis.pdfPath, pdfBytes);
globalThis.resultPath = globalThis.pdfPath;
